-- GeoBrix Unity Catalog functions: setup.
-- Run this file first. It builds the small sample tables the other files query.
-- The files use the catalog geospatial_docs and the schema geobrix_uc: change both names below
-- (and in the other files) when you installed the functions somewhere else.

-- cid: use_catalog
USE CATALOG geospatial_docs;

-- cid: use_schema
USE SCHEMA geobrix_uc;

-- cid: check_functions_installed
-- Shows that the GeoBrix functions are in the schema: this counts them.
SELECT count(*) AS geobrix_functions
FROM information_schema.routines
WHERE routine_schema = 'geobrix_uc' AND routine_name LIKE 'gbx_%';

-- cid: create_ex_rasters
-- Two tiny GeoTIFFs become tiles: a 24 x 24 pixel DEM and a 5-band scene (red, green, blue, near infrared, shortwave infrared),
-- both in British National Grid (EPSG:27700) with 10 m pixels. gbx_rst_fromcontent reads the file bytes.
-- To use your own file instead, read it with read_files(<path>, format => 'binaryFile') and pass its content.
CREATE OR REPLACE TABLE ex_rasters AS
SELECT name, gbx_rst_fromcontent(unhex(hexbytes), 'GTiff') AS tile
FROM VALUES
  ('dem',
