-- cid: add_scene_in_wgs84
-- The same scene warped to longitude and latitude (EPSG:4326), for the H3 and quadbin examples.
INSERT INTO ex_rasters
SELECT 'scene_wgs84', gbx_rst_transformcrs(tile, 'EPSG:4326') FROM ex_rasters WHERE name = 'scene';

-- cid: create_ex_dem_tiles
-- The DEM cut into 12 x 12 pixel tiles, with a tile key (the window) and a bounding box for each.
-- Aggregation recipes and procedures take tiles in this shape: a key column and a tile column.
CREATE OR REPLACE TABLE ex_dem_tiles AS
SELECT concat(t.window.col_off, '_', t.window.row_off) AS tile_key,
       struct(t.cellid, t.raster, t.path, t.path_mode, t.window, t.clip_polygon, t.clip_crs, t.crs, t.metadata) AS tile
FROM ex_rasters AS r, LATERAL gbx_rst_retile(r.tile, 12, 12) AS t
WHERE r.name = 'dem';

-- cid: create_ex_parcels
-- Land parcels in British National Grid (EPSG:27700). District A is a clean set of neighbours,
-- district B has two overlapping parcels, and parcel 6 is a bow-tie (an invalid polygon).
CREATE OR REPLACE TABLE ex_parcels AS
SELECT id, district, name, st_geomfromwkt(wkt, 27700) AS geom
FROM VALUES
  (1, 'A', 'north field',  'POLYGON((530000 180100, 530100 180100, 530100 180200, 530000 180200, 530000 180100))'),
  (2, 'A', 'middle field', 'POLYGON((530000 180000, 530100 180000, 530100 180100, 530000 180100, 530000 180000))'),
  (3, 'A', 'east field',   'POLYGON((530100 180000, 530250 180000, 530250 180200, 530100 180200, 530100 180000))'),
  (4, 'B', 'west yard',    'POLYGON((531000 181000, 531150 181000, 531150 181100, 531000 181100, 531000 181000))'),
  (5, 'B', 'overlap yard', 'POLYGON((531100 181000, 531250 181000, 531250 181100, 531100 181100, 531100 181000))'),
  (6, 'C', 'bow-tie',      'POLYGON((532000 182000, 532100 182100, 532100 182000, 532000 182100, 532000 182000))')
  AS t(id, district, name, wkt);

-- cid: create_ex_points
-- Twelve sensor readings around central London, in longitude and latitude (EPSG:4326).
CREATE OR REPLACE TABLE ex_points AS
SELECT id, longitude, latitude, value, st_point(longitude, latitude, 4326) AS geom
FROM VALUES
  (1, -0.1278, 51.5074, 12.0), (2, -0.1180, 51.5033, 15.5), (3, -0.1246, 51.5007, 11.2),
  (4, -0.1419, 51.5014, 18.4), (5, -0.1357, 51.5101, 14.1), (6, -0.1195, 51.5139, 16.8),
  (7, -0.1100, 51.5072, 13.3), (8, -0.1300, 51.5200, 19.0), (9, -0.1500, 51.5100, 10.5),
  (10, -0.1250, 51.4950, 17.7), (11, -0.1050, 51.5200, 12.9), (12, -0.1400, 51.4900, 15.0)
  AS t(id, longitude, latitude, value);

-- cid: create_ex_roads
-- A few features for vector tiles. The attributes are a struct, as in a real feature table.
CREATE OR REPLACE TABLE ex_roads AS
SELECT id, st_geomfromwkt(wkt, 4326) AS geom, named_struct('name', name, 'lanes', lanes) AS attrs
FROM VALUES
  (1, 'LINESTRING(-0.1500 51.5000, -0.1250 51.5050, -0.1000 51.5100)', 'Embankment', 2),
  (2, 'LINESTRING(-0.1300 51.4900, -0.1280 51.5070, -0.1260 51.5250)', 'Whitehall', 3),
  (3, 'POLYGON((-0.1400 51.5000, -0.1300 51.5000, -0.1300 51.5080, -0.1400 51.5080, -0.1400 51.5000))', 'Park', 0)
  AS t(id, wkt, name, lanes);

-- cid: create_ex_legacy_geoms
-- Geometries in the legacy Mosaic struct form (typeId 1 point, 5 polygon), for the migration example.
CREATE OR REPLACE TABLE ex_legacy_geoms AS
SELECT 1 AS id,
       named_struct('typeId', 1, 'srid', 27700,
         'boundaries', array(array(array(530500.0D, 180500.0D))),
         'holes', CAST(array() AS ARRAY<ARRAY<ARRAY<ARRAY<DOUBLE>>>>)) AS geom
UNION ALL
SELECT 2,
       named_struct('typeId', 5, 'srid', 27700,
         'boundaries', array(array(array(530000.0D, 180000.0D), array(530100.0D, 180000.0D), array(530100.0D, 180100.0D), array(530000.0D, 180100.0D), array(530000.0D, 180000.0D))),
         'holes', CAST(array() AS ARRAY<ARRAY<ARRAY<ARRAY<DOUBLE>>>>));

-- cid: list_sample_tables
SELECT table_name FROM information_schema.tables WHERE table_schema = 'geobrix_uc' AND table_name LIKE 'ex_%' ORDER BY table_name;
